//! `KyutaiEngine` on the reduced Kyutai fixtures (`fixtures/kyutai-lm`,
//! generated by Kyutai's own `moshi` crate): through the `Engine` trait, the
//! engine must reproduce Kyutai's recorded generation exactly (greedy
//! decoding), and it must reject what these checkpoints cannot serve.

use std::collections::VecDeque;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

use s2s_core::streams::FRAME_SAMPLES;
use s2s_infer::{FrameCodec, KyutaiEngine, KyutaiEngineConfig, KyutaiModel};
use s2s_kernels::reference::sampling::SamplingParams;
use s2s_model::kyutai::{AsrConfig, AsrMsg, LmConfig, LmModel, MultistreamConfig};
use s2s_server::engine::silent_frame;
use s2s_server::protocol::TurnEvent;
use s2s_server::{Engine, EngineError, EngineEvent, FrameInput, FrameOutput, Mode, SessionConfig};
use s2s_tools::{TokenPiece, TokenizerInfo};
use serde_json::{json, Value};

fn fixture_dir(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures/kyutai-lm")
        .join(name)
}

fn read_json(path: PathBuf) -> Value {
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn u32s(v: &Value) -> Vec<u32> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_u64().unwrap() as u32)
        .collect()
}

fn rows(v: &Value) -> Vec<Vec<u32>> {
    v.as_array().unwrap().iter().map(u32s).collect()
}

fn load_lm(name: &str) -> (LmModel, Value, Value) {
    let dir = fixture_dir(name);
    let cfg = read_json(dir.join("config.json"));
    let lm_cfg = LmConfig::from_path(dir.join("config.json")).unwrap();
    let lm = LmModel::load_safetensors(&lm_cfg, dir.join("model.safetensors")).unwrap();
    (lm, cfg["driver"].clone(), read_json(dir.join("trace.json")))
}

fn moshi() -> (KyutaiModel, Value) {
    let (lm, driver, trace) = load_lm("moshi");
    let driver: MultistreamConfig = serde_json::from_value(driver["gen"].clone()).unwrap();
    (KyutaiModel::Moshi { lm, driver }, trace)
}

fn stt() -> (KyutaiModel, Value) {
    let (lm, driver, trace) = load_lm("stt");
    let asr = AsrConfig {
        asr_delay_in_tokens: driver["asr_delay_in_tokens"].as_u64().unwrap() as usize,
        conditioning_delay: driver["conditioning_delay"].as_f64().map(|d| d as f32),
        conditioning_learnt_padding: false,
        temperature: Some(0.0),
    };
    (KyutaiModel::Stt { lm, asr }, trace)
}

/// The fixtures' 32 text ids: 0..4 special (0 = end of padding, 3 =
/// padding), the rest one letter each.
struct LetterTok;

const SPECIALS: u32 = 4;

fn letter(id: u32) -> u8 {
    b'a' + (id - SPECIALS) as u8
}

impl TokenizerInfo for LetterTok {
    fn vocab_size(&self) -> usize {
        32
    }
    fn token(&self, id: u32) -> TokenPiece {
        if id < SPECIALS {
            TokenPiece::Special(format!("<s{id}>"))
        } else {
            TokenPiece::Bytes(vec![letter(id)])
        }
    }
    fn tokenize(&self, text: &[u8]) -> Vec<u32> {
        text.iter().map(|&b| (b - b'a') as u32 + SPECIALS).collect()
    }
}

/// Text the engine should send for these token ids.
fn letters(ids: &[u32]) -> String {
    ids.iter()
        .filter(|&&t| (SPECIALS..32).contains(&t))
        .map(|&t| letter(t) as char)
        .collect()
}

/// Replays scripted codes on `encode` and records what it is asked to
/// decode (returning a constant frame tagged by the first code).
struct ReplayCodec {
    codebooks: usize,
    size: u32,
    script: Arc<Mutex<VecDeque<Vec<u32>>>>,
    decoded: Arc<Mutex<Vec<Vec<u32>>>>,
}

impl FrameCodec for ReplayCodec {
    fn codebooks(&self) -> usize {
        self.codebooks
    }
    fn codebook_size(&self) -> u32 {
        self.size
    }
    fn encode(&mut self, pcm: &[f32]) -> Vec<u32> {
        assert_eq!(pcm.len(), FRAME_SAMPLES);
        self.script
            .lock()
            .unwrap()
            .pop_front()
            .expect("codec script ran out")
    }
    fn decode(&mut self, codes: &[u32]) -> Vec<f32> {
        self.decoded.lock().unwrap().push(codes.to_vec());
        vec![(codes[0] + 1) as f32 / 100.0; FRAME_SAMPLES]
    }
    fn silence_codes(&self) -> Vec<u32> {
        vec![0; self.codebooks]
    }
}

type Shared<T> = Arc<Mutex<T>>;

struct Harness {
    engine: KyutaiEngine,
    script: Shared<VecDeque<Vec<u32>>>,
    decoded: Shared<Vec<Vec<u32>>>,
}

fn greedy() -> KyutaiEngineConfig {
    KyutaiEngineConfig {
        text_sampling: SamplingParams::GREEDY,
        audio_sampling: SamplingParams::GREEDY,
        seed: 0,
        max_frames: 64,
    }
}

fn harness(model: KyutaiModel, codebooks: usize, size: u32, cfg: KyutaiEngineConfig) -> Harness {
    let script: Shared<VecDeque<Vec<u32>>> = Arc::default();
    let decoded: Shared<Vec<Vec<u32>>> = Arc::default();
    let (s, d) = (script.clone(), decoded.clone());
    let engine = KyutaiEngine::new(
        model,
        Arc::new(LetterTok),
        move || {
            Box::new(ReplayCodec {
                codebooks,
                size,
                script: s.clone(),
                decoded: d.clone(),
            }) as Box<dyn FrameCodec>
        },
        cfg,
    )
    .unwrap();
    Harness {
        engine,
        script,
        decoded,
    }
}

fn session(mode: Mode) -> SessionConfig {
    SessionConfig {
        system_prompt: String::new(),
        tools: vec![],
        voice: None,
        mode,
    }
}

/// Run one session over `codes` (one row per frame); returns each frame's
/// output.
fn run(h: &mut Harness, id: u64, codes: &[Vec<u32>]) -> Result<Vec<FrameOutput>, EngineError> {
    h.script.lock().unwrap().extend(codes.iter().cloned());
    let mut outs = vec![];
    for (i, _) in codes.iter().enumerate() {
        let mut input = [FrameInput {
            session: id,
            frame_index: i as u64,
            audio: silent_frame(),
            injections: vec![],
        }];
        let mut out = [FrameOutput::new()];
        h.engine.step(&mut input, &mut out)?;
        let [out] = out;
        outs.push(out);
    }
    Ok(outs)
}

fn assistant_text(outs: &[FrameOutput]) -> String {
    outs.iter()
        .flat_map(|o| &o.events)
        .filter_map(|e| match e {
            EngineEvent::AssistantText(t) => Some(t.as_str()),
            _ => None,
        })
        .collect()
}

#[test]
fn moshi_session_reproduces_kyutai_generation() {
    let (model, trace) = moshi();
    let mut h = harness(model, 8, 16, greedy());
    let user_audio = rows(&trace["user_audio"]);
    h.engine.open_session(7, &session(Mode::S2s)).unwrap();
    assert_eq!(h.engine.current_session(), Some(7));
    let outs = run(&mut h, 7, &user_audio).unwrap();

    // Text: Kyutai's sampled tokens, minus padding / specials.
    let kyutai_text = u32s(&trace["state_text_tokens"]);
    assert_eq!(assistant_text(&outs), letters(&kyutai_text));

    // Audio: every frame complete in undelayed time, decoded in order, as in
    // Kyutai's token grid (generated codebooks only).
    let grid = rows(&trace["state_audio_tokens"]);
    let (delay, gen, pad) = (2usize, 8usize, 16u32);
    let expected: Vec<Vec<u32>> = (0..user_audio.len())
        .filter(|&i| i + 1 > delay)
        .map(|i| grid[i - delay].clone())
        .filter(|r| r.iter().all(|&c| c < pad))
        .map(|r| r[..gen].to_vec())
        .collect();
    let decoded = h.decoded.lock().unwrap().clone();
    assert!(!decoded.is_empty(), "fixture should yield decoded frames");
    assert_eq!(decoded, expected);
    assert_eq!(
        decoded.last().unwrap().clone(),
        u32s(&trace["state_last_audio_tokens"])[..gen].to_vec()
    );
    // Decoded PCM lands in the output frame; frames before the first
    // complete one stay silent.
    let first = outs.iter().position(|o| o.audio[0] != 0.0).unwrap();
    assert!(first >= delay);
    assert!(outs[..first]
        .iter()
        .all(|o| o.audio.iter().all(|&x| x == 0.0)));

    // Closing gives the model back with a clear cache: a second session
    // generates exactly the same thing.
    h.engine.close_session(7);
    assert_eq!(h.engine.current_session(), None);
    h.decoded.lock().unwrap().clear();
    h.engine.open_session(8, &session(Mode::S2s)).unwrap();
    let again = run(&mut h, 8, &user_audio).unwrap();
    assert_eq!(assistant_text(&again), letters(&kyutai_text));
    assert_eq!(*h.decoded.lock().unwrap(), expected);
}

#[test]
fn moshi_session_reports_assistant_turns() {
    let (model, trace) = moshi();
    let mut h = harness(model, 8, 16, greedy());
    h.engine.open_session(1, &session(Mode::S2s)).unwrap();
    let outs = run(&mut h, 1, &rows(&trace["user_audio"])).unwrap();
    let text = u32s(&trace["state_text_tokens"]);
    let started = outs
        .iter()
        .flat_map(|o| &o.events)
        .any(|e| *e == EngineEvent::Turn(TurnEvent::AssistantStarted));
    // The assistant "speaks" whenever its text stream is not padding.
    assert_eq!(started, text.iter().any(|&t| t != 3));
}

#[test]
fn stt_session_transcribes_like_kyutai() {
    let (model, trace) = stt();
    let mut h = harness(model, 8, 16, greedy());
    h.engine.open_session(3, &session(Mode::Stt)).unwrap();
    let outs = run(&mut h, 3, &rows(&trace["codes"])).unwrap();
    let ours: Vec<String> = outs
        .iter()
        .flat_map(|o| &o.events)
        .filter_map(|e| match e {
            EngineEvent::UserText(t) => Some(t.clone()),
            _ => None,
        })
        .collect();
    let kyutai_msgs: Vec<AsrMsg> = serde_json::from_value(trace["asr_msgs"].clone()).unwrap();
    let theirs: Vec<String> = kyutai_msgs
        .iter()
        .filter_map(|m| match m {
            AsrMsg::Word { tokens, .. } => Some(letters(tokens)),
            _ => None,
        })
        .filter(|w| !w.is_empty())
        .collect();
    assert!(!theirs.is_empty(), "fixture should produce a word");
    assert_eq!(ours, theirs);
    // STT sends no audio.
    assert!(outs.iter().all(|o| o.audio.iter().all(|&x| x == 0.0)));
}

#[test]
fn rejects_what_kyutai_checkpoints_cannot_serve() {
    let (model, _) = moshi();
    let mut h = harness(model, 8, 16, greedy());
    let rejected = |r: Result<(), EngineError>| matches!(r, Err(EngineError::Rejected(_)));
    assert!(rejected(h.engine.open_session(1, &session(Mode::Tts))));
    assert!(rejected(h.engine.open_session(1, &session(Mode::Stt))));
    let mut with_tools = session(Mode::S2s);
    with_tools.tools = vec![json!({"name": "get_weather", "parameters": {"type": "object"}})];
    assert!(rejected(h.engine.open_session(1, &with_tools)));
    // One session at a time.
    h.engine.open_session(1, &session(Mode::S2s)).unwrap();
    assert!(rejected(h.engine.open_session(2, &session(Mode::S2s))));
    // A step for a session it doesn't hold fails, and frees the model.
    assert!(run(&mut h, 2, &[vec![0; 8]]).is_err());
    h.engine.open_session(2, &session(Mode::S2s)).unwrap();

    let (stt_model, _) = stt();
    let mut h = harness(stt_model, 8, 16, greedy());
    assert!(rejected(h.engine.open_session(1, &session(Mode::S2s))));
    h.engine.open_session(1, &session(Mode::Stt)).unwrap();
}

#[test]
fn rejects_mismatched_codecs_and_models() {
    let (model, _) = moshi();
    let mut wrong_books = harness(model, 4, 16, greedy());
    assert!(matches!(
        wrong_books.engine.open_session(1, &session(Mode::S2s)),
        Err(EngineError::Rejected(_))
    ));
    let (model, _) = moshi();
    let mut wrong_size = harness(model, 8, 2048, greedy());
    assert!(matches!(
        wrong_size.engine.open_session(1, &session(Mode::S2s)),
        Err(EngineError::Rejected(_))
    ));
    // A failed open leaves the model available.
    wrong_size.engine.close_session(1);
    assert_eq!(wrong_size.engine.current_session(), None);

    // The drivers must match the checkpoint kind.
    let codec = || -> Box<dyn FrameCodec> { unreachable!() };
    let (KyutaiModel::Stt { lm, .. }, _) = stt() else {
        unreachable!()
    };
    let driver = MultistreamConfig::v0_1();
    let as_moshi = KyutaiModel::Moshi { lm, driver };
    assert!(KyutaiEngine::new(as_moshi, Arc::new(LetterTok), codec, greedy()).is_err());
    let (KyutaiModel::Moshi { lm, .. }, _) = moshi() else {
        unreachable!()
    };
    let asr = AsrConfig {
        asr_delay_in_tokens: 3,
        conditioning_delay: None,
        conditioning_learnt_padding: false,
        temperature: None,
    };
    let as_stt = KyutaiModel::Stt { lm, asr };
    assert!(KyutaiEngine::new(as_stt, Arc::new(LetterTok), codec, greedy()).is_err());
}

#[test]
fn a_session_past_max_frames_fails_and_frees_the_model() {
    let (model, trace) = moshi();
    let cfg = KyutaiEngineConfig {
        max_frames: 4,
        ..greedy()
    };
    let mut h = harness(model, 8, 16, cfg);
    h.engine.open_session(1, &session(Mode::S2s)).unwrap();
    let codes = rows(&trace["user_audio"]);
    assert!(matches!(
        run(&mut h, 1, &codes),
        Err(EngineError::StepFailed(_))
    ));
    assert_eq!(h.engine.current_session(), None);
    h.script.lock().unwrap().clear();
    // The server closes the failed session; then a new one starts fresh.
    h.engine.close_session(1);
    h.engine.open_session(2, &session(Mode::S2s)).unwrap();
    let outs = run(&mut h, 2, &codes[..3]).unwrap();
    assert_eq!(outs.len(), 3);
}
